grid = grid_str.split('\n')
max_len = max(len(line) for line in grid)
grid = [line.ljust(max_len) for line in grid]

def is_rect(r1, c1, r2, c2):
    for c in range(c1, c2 + 1):
        if grid[r1][c] not in ('#', '█'): return False
    for c in range(c1, c2 + 1):
        if grid[r2][c] not in ('#', '█'): return False
    for r in range(r1, r2 + 1):
        if grid[r][c1] not in ('#', '█'): return False
    for r in range(r1, r2 + 1):
        if grid[r][c2] not in ('#', '█'): return False
    return True

rects = []
rows = len(grid)
cols = len(grid[0])
for r1 in range(rows):
    for c1 in range(cols):
        if grid[r1][c1] not in ('#', '█'): continue
        for r2 in range(r1 + 2, rows):
            for c2 in range(c1 + 2, cols):
                if is_rect(r1, c1, r2, c2):
                    rects.append((r1, c1, r2, c2))

print(len(rects))"}
